      "svg": "<svg viewBox=\"0 0 1100 1100\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"70\" font-size=\"36\" font-weight=\"bold\" fill=\"#ffd700\" text-anchor=\"middle\">Five-Minute Daily Diagnostic</text><text x=\"550\" y=\"115\" font-size=\"24\" fill=\"#888\" text-anchor=\"middle\">From task list to A-1 in five minutes</text><rect x=\"80\" y=\"170\" width=\"940\" height=\"140\" rx=\"20\" fill=\"rgba(99,102,241,0.15)\" stroke=\"#6366f1\" stroke-width=\"3\"/><text x=\"550\" y=\"215\" font-size=\"26\" font-weight=\"bold\" fill=\"#6366f1\" text-anchor=\"middle\">Step 1: List Every Task</text><text x=\"550\" y=\"260\" font-size=\"22\" fill=\"#fff\" text-anchor=\"middle\">Everything on your plate today</text><text x=\"550\" y=\"295\" font-size=\"18\" fill=\"#888\" text-anchor=\"middle\">Brain dump, no editing yet</text><rect x=\"80\" y=\"330\" width=\"940\" height=\"140\" rx=\"20\" fill=\"rgba(139,92,246,0.15)\" stroke=\"#8b5cf6\" stroke-width=\"3\"/><text x=\"550\" y=\"375\" font-size=\"26\" font-weight=\"bold\" fill=\"#8b5cf6\" text-anchor=\"middle\">Step 2: Circle the Vital 20%</text><text x=\"550\" y=\"420\" font-size=\"22\" fill=\"#fff\" text-anchor=\"middle\">Most likely to produce 80% of impact</text><text x=\"550\" y=\"455\" font-size=\"18\" fill=\"#888\" text-anchor=\"middle\">Pareto filter</text><rect x=\"80\" y=\"490\" width=\"940\" height=\"140\" rx=\"20\" fill=\"rgba(245,158,11,0.15)\" stroke=\"#f59e0b\" stroke-width=\"3\"/><text x=\"550\" y=\"535\" font-size=\"26\" font-weight=\"bold\" fill=\"#f59e0b\" text-anchor=\"middle\">Step 3: Apply Three Questions</text><text x=\"550\" y=\"580\" font-size=\"22\" fill=\"#fff\" text-anchor=\"middle\">Long-term, opportunity cost, only-you</text><text x=\"550\" y=\"615\" font-size=\"18\" fill=\"#888\" text-anchor=\"middle\">Tie-breaker among the 20%</text><rect x=\"80\" y=\"650\" width=\"940\" height=\"140\" rx=\"20\" fill=\"rgba(16,185,129,0.15)\" stroke=\"#10b981\" stroke-width=\"3\"/><text x=\"550\" y=\"695\" font-size=\"26\" font-weight=\"bold\" fill=\"#10b981\" text-anchor=\"middle\">Step 4: Stamp A-1</text><text x=\"550\" y=\"740\" font-size=\"22\" fill=\"#fff\" text-anchor=\"middle\">The highest scorer becomes the frog</text><text x=\"550\" y=\"775\" font-size=\"18\" fill=\"#888\" text-anchor=\"middle\">Confident designation</text><rect x=\"80\" y=\"810\" width=\"940\" height=\"140\" rx=\"20\" fill=\"rgba(255,215,0,0.15)\" stroke=\"#ffd700\" stroke-width=\"3\"/><text x=\"550\" y=\"855\" font-size=\"26\" font-weight=\"bold\" fill=\"#ffd700\" text-anchor=\"middle\">Step 5: Pre-empt and Begin</text><text x=\"550\" y=\"900\" font-size=\"22\" fill=\"#fff\" text-anchor=\"middle\">Open file, stage, write first sentence</text><text x=\"550\" y=\"935\" font-size=\"18\" fill=\"#888\" text-anchor=\"middle\">Execute immediately</text></svg>",
